#include "pe_utils.h" /* -> woody.h: t_file, t_file_ops, STUBPE_P_*, ALIGN_UP, magic */
#include "stubpe32.h" /* stubpe32_bin / stubpe32_bin_len (generated by xxd) */
#include "stubpe64.h" /* stubpe64_bin / stubpe64_bin_len (generated by xxd) */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* PE/COFF image parsing: validate the DOS/NT headers, bounds-check the header
 * tables, and resolve the file header, optional header and section table. The
 * region a packer encrypts is the entry-point section, located the same way the
 * ELF backend finds its executable segment. The packing code below builds on
 * this. */

static int pe_in_bounds(size_t size, uint64_t off, uint64_t len)
{
	return (off <= size && len <= size - off);
}

int pe_detect(const uint8_t *data, size_t size)
{
	uint32_t lfanew;

	if (size < sizeof(t_pe_dos_header))
		return (0);
	if (((const t_pe_dos_header *)data)->e_magic != PE_DOS_MAGIC)
		return (0);
	lfanew = ((const t_pe_dos_header *)data)->e_lfanew;
	if (!pe_in_bounds(size, lfanew, 4))
		return (0);
	return (*(const uint32_t *)(data + lfanew) == PE_NT_MAGIC);
}

int pe_parse(const uint8_t *data, size_t size, t_pe *out)
{
	const t_pe_dos_header *dos = (const t_pe_dos_header *)data;
	uint32_t			   nt;
	uint16_t			   opt_magic;
	uint64_t			   sec_off;
	uint64_t			   sec_bytes;

	memset(out, 0, sizeof(*out));
	out->data = data;
	out->size = size;
	if (!pe_detect(data, size))
		return (fprintf(stderr, "not a PE image\n"), -1);
	nt = dos->e_lfanew;
	/* PE signature (4) + file header follows */
	if (!pe_in_bounds(size, nt + 4, sizeof(t_pe_file_header)))
		return (fprintf(stderr, "PE: truncated file header\n"), -1);
	out->fh = (const t_pe_file_header *)(data + nt + 4);
	/* optional header starts right after the file header */
	out->opt = (const uint8_t *)out->fh + sizeof(t_pe_file_header);
	if (!pe_in_bounds(size,
					  (const uint8_t *)out->opt - data,
					  out->fh->SizeOfOptionalHeader))
		return (fprintf(stderr, "PE: truncated optional header\n"), -1);
	if (out->fh->SizeOfOptionalHeader < sizeof(uint16_t))
		return (fprintf(stderr, "PE: no optional header\n"), -1);
	opt_magic = *(const uint16_t *)out->opt;
	if (opt_magic == PE_OPT_MAGIC_PE32P)
	{
		const t_pe_opt_header64 *o = out->opt;

		if (out->fh->SizeOfOptionalHeader < sizeof(*o))
			return (fprintf(stderr, "PE: short PE32+ optional header\n"), -1);
		out->is64 = 1;
		out->entry_rva = o->AddressOfEntryPoint;
		out->image_base = o->ImageBase;
	}
	else if (opt_magic == PE_OPT_MAGIC_PE32)
	{
		const t_pe_opt_header32 *o = out->opt;

		if (out->fh->SizeOfOptionalHeader < sizeof(*o))
			return (fprintf(stderr, "PE: short PE32 optional header\n"), -1);
		out->is64 = 0;
		out->entry_rva = o->AddressOfEntryPoint;
		out->image_base = o->ImageBase;
	}
	else
		return (fprintf(stderr, "PE: unknown optional magic %#x\n", opt_magic),
				-1);
	/* section table follows the optional header */
	sec_off = ((const uint8_t *)out->opt - data)
			  + out->fh->SizeOfOptionalHeader;
	sec_bytes = (uint64_t)out->fh->NumberOfSections
				* sizeof(t_pe_section_header);
	if (!pe_in_bounds(size, sec_off, sec_bytes))
		return (fprintf(stderr, "PE: truncated section table\n"), -1);
	out->sections = (const t_pe_section_header *)(data + sec_off);
	return (0);
}

/* Locate the section whose virtual range contains the entry RVA. Returns its
 * index, or -1 if the entry falls outside every section. */
static int pe_entry_section(const t_pe *pe)
{
	for (uint16_t i = 0; i < pe->fh->NumberOfSections; i++)
	{
		const t_pe_section_header *s = &pe->sections[i];
		const uint32_t			   lo = s->VirtualAddress;
		const uint32_t			   hi = s->VirtualAddress + s->VirtualSize;

		if (pe->entry_rva >= lo && pe->entry_rva < hi)
			return ((int)i);
	}
	return (-1);
}

/* Render the 8-byte, not-necessarily-terminated section name safely. */
static void pe_section_name(const t_pe_section_header *s, char out[9])
{
	memcpy(out, s->Name, PE_SIZEOF_SHORT_NAME);
	out[PE_SIZEOF_SHORT_NAME] = '\0';
}

int pe_inspect(const uint8_t *data, size_t size)
{
	t_pe pe;
	int	 entry_idx;

	if (pe_parse(data, size, &pe))
		return (-1);
	printf("PE image: %s, machine %#x, %u section(s)\n",
		   pe.is64 ? "PE32+ (x64)" : "PE32 (x86)",
		   pe.fh->Machine,
		   pe.fh->NumberOfSections);
	printf("ImageBase %#llx, AddressOfEntryPoint (RVA) %#x\n",
		   (unsigned long long)pe.image_base,
		   pe.entry_rva);
	entry_idx = pe_entry_section(&pe);
	for (uint16_t i = 0; i < pe.fh->NumberOfSections; i++)
	{
		const t_pe_section_header *s = &pe.sections[i];
		char					   name[9];

		pe_section_name(s, name);
		printf(
			"  [%2u] %-8s RVA %#08x VSize %#08x  file[%#08x..%#08x) %c%c%c%s\n",
			i,
			name,
			s->VirtualAddress,
			s->VirtualSize,
			s->PointerToRawData,
			s->PointerToRawData + s->SizeOfRawData,
			(s->Characteristics & PE_SCN_MEM_READ) ? 'r' : '-',
			(s->Characteristics & PE_SCN_MEM_WRITE) ? 'w' : '-',
			(s->Characteristics & PE_SCN_MEM_EXECUTE) ? 'x' : '-',
			(int)i == entry_idx ? "  <- entry" : "");
	}
	if (entry_idx < 0)
		return (fprintf(stderr, "PE: entry point outside all sections\n"), -1);
	{
		const t_pe_section_header *s = &pe.sections[entry_idx];
		char					   name[9];

		pe_section_name(s, name);
		printf("entry section: %s, would encrypt file[%#x..%#x) (%u bytes)\n",
			   name,
			   s->PointerToRawData,
			   s->PointerToRawData + s->SizeOfRawData,
			   s->SizeOfRawData);
	}
	return (0);
}

/* ======================== PE32+ (x64) packing ========================= */
/* Reuses t_file and the shared pipeline in main.c (key gen, compress+encrypt,
 * write). Only the container work is PE-specific: validate the input, point the
 * pipeline at the entry section's raw bytes, then append a .woody section
 * holding the stub + payload, repoint the entry, and make the host code section
 * writable so the stub can expand into it without any API call. */

#define PE_SCN_WOODY                                                           \
	(PE_SCN_CNT_CODE | PE_SCN_MEM_EXECUTE | PE_SCN_MEM_READ | PE_SCN_MEM_WRITE)

/* Highest VA consumed by any section, rounded to section alignment. */
static uint64_t pe_va_end(const t_pe *pe, uint32_t sect_align)
{
	uint64_t end = 0;

	for (uint16_t i = 0; i < pe->fh->NumberOfSections; i++)
	{
		const t_pe_section_header *s = &pe->sections[i];
		uint32_t vsz = s->VirtualSize ? s->VirtualSize : s->SizeOfRawData;
		uint64_t e = ALIGN_UP((uint64_t)s->VirtualAddress + vsz, sect_align);

		if (e > end)
			end = e;
	}
	return (end);
}

static int validate_pe(t_file *f)
{
	t_pe					   pe;
	uint32_t				   fa;
	uint32_t				   sa;
	uint32_t				   hdrsz;
	const t_pe_section_header *es;
	int						   ei;
	size_t					   slot;

	if (pe_parse(f->data, f->size, &pe))
		return (-1);
	if (pe.is64)
	{
		const t_pe_opt_header64 *o = pe.opt;

		fa = o->FileAlignment;
		sa = o->SectionAlignment;
		hdrsz = o->SizeOfHeaders;
		if (pe.fh->Machine != PE_MACHINE_AMD64)
			return (fprintf(stderr, "PE: unexpected machine for PE32+\n"), -1);
	}
	else
	{
		const t_pe_opt_header32 *o = pe.opt;

		fa = o->FileAlignment;
		sa = o->SectionAlignment;
		hdrsz = o->SizeOfHeaders;
		if (pe.fh->Machine != PE_MACHINE_I386)
			return (fprintf(stderr, "PE: unexpected machine for PE32\n"), -1);
	}
	if (!fa || (fa & (fa - 1)) || !sa || (sa & (sa - 1)))
		return (fprintf(stderr, "PE: bad alignment fields\n"), -1);
	ei = pe_entry_section(&pe);
	if (ei < 0)
		return (fprintf(stderr, "PE: entry point outside all sections\n"), -1);
	es = &pe.sections[ei];
	if (!(es->Characteristics & (PE_SCN_MEM_EXECUTE | PE_SCN_CNT_CODE)))
		return (fprintf(stderr, "PE: entry section is not executable\n"), -1);
	if (!es->SizeOfRawData
		|| !pe_in_bounds(f->size, es->PointerToRawData, es->SizeOfRawData))
		return (fprintf(stderr, "PE: entry section raw data out of range\n"),
				-1);
	slot = ((const uint8_t *)pe.sections - f->data)
		   + (size_t)pe.fh->NumberOfSections * sizeof(t_pe_section_header);
	if (slot + sizeof(t_pe_section_header) > hdrsz)
		return (fprintf(stderr, "PE: no header room for another section\n"),
				-1);
	return (0);
}

static int find_region_pe(t_file *f)
{
	t_pe					   pe;
	const t_pe_section_header *es;
	int						   ei;

	if (pe_parse(f->data, f->size, &pe))
		return (-1);
	ei = pe_entry_section(&pe);
	if (ei < 0)
		return (-1);
	es = &pe.sections[ei];
	f->region_off = es->PointerToRawData;
	f->region_len = es->SizeOfRawData;
	f->entry = pe.entry_rva;
	return (0);
}

/* Host is x86 LE; memcpy handles unaligned stores. */
static void put_le64(uint8_t *p, uint64_t v)
{
	memcpy(p, &v, sizeof(v));
}

/* Fill the stub parameter block (found by its magic). Deltas are RVA
 * differences, invariant under relocation. */
static int fill_stub_pe64(uint8_t *stub,
						  size_t   stub_len,
						  uint32_t stub_rva,
						  uint32_t dst_rva,
						  t_file  *f)
{
	const uint64_t magic = STUB_PARAMS_MAGIC;
	size_t		   i = 0;

	while (i + sizeof(magic) <= stub_len
		   && memcmp(stub + i, &magic, sizeof(magic)) != 0)
		i++;
	if (i + STUBPE_P_NONCE + sizeof(f->nonce) > stub_len)
		return (fprintf(stderr, "PE: stub param block not found\n"), -1);
	put_le64(stub + i + STUBPE_P_ENTRY_DELTA,
			 (uint64_t)((int64_t)f->entry - (int64_t)stub_rva));
	put_le64(stub + i + STUBPE_P_REGION_DELTA,
			 (uint64_t)((int64_t)dst_rva - (int64_t)stub_rva));
	put_le64(stub + i + STUBPE_P_REGION_LEN, f->region_len);
	put_le64(stub + i + STUBPE_P_SRC_DELTA, stub_len); /* blob follows stub */
	put_le64(stub + i + STUBPE_P_COMP_LEN, f->comp_len);
	memcpy(stub + i + STUBPE_P_KEY, f->key, sizeof(f->key));
	memcpy(stub + i + STUBPE_P_NONCE, f->nonce, sizeof(f->nonce));
	return (0);
}

static void put_le32(uint8_t *p, uint32_t v)
{
	memcpy(p, &v, sizeof(v));
}

/* PE32 (x86) variant: 4-byte deltas at the STUBPE32_P_* offsets. */
static int fill_stub_pe32(uint8_t *stub,
						  size_t   stub_len,
						  uint32_t stub_rva,
						  uint32_t dst_rva,
						  t_file  *f)
{
	const uint64_t magic = STUB_PARAMS_MAGIC;
	size_t		   i = 0;

	while (i + sizeof(magic) <= stub_len
		   && memcmp(stub + i, &magic, sizeof(magic)) != 0)
		i++;
	if (i + STUBPE32_P_NONCE + sizeof(f->nonce) > stub_len)
		return (fprintf(stderr, "PE: stub param block not found\n"), -1);
	put_le32(stub + i + STUBPE32_P_ENTRY_DELTA, f->entry - stub_rva);
	put_le32(stub + i + STUBPE32_P_REGION_DELTA, dst_rva - stub_rva);
	put_le32(stub + i + STUBPE32_P_REGION_LEN, (uint32_t)f->region_len);
	put_le32(stub + i + STUBPE32_P_SRC_DELTA, (uint32_t)stub_len);
	put_le32(stub + i + STUBPE32_P_COMP_LEN, (uint32_t)f->comp_len);
	memcpy(stub + i + STUBPE32_P_KEY, f->key, sizeof(f->key));
	memcpy(stub + i + STUBPE32_P_NONCE, f->nonce, sizeof(f->nonce));
	return (0);
}

/* Geometry of the appended .woody section, worked out once up front so the body
 * of build_output_pe can stay about emitting bytes rather than computing
 * offsets. The class-specific inputs (stub blob, alignments) are resolved here
 * too, leaving only the stub param width to branch on at fill time. */
typedef struct s_pe_layout
{
	uint32_t	   fa;		 /* FileAlignment */
	uint32_t	   sa;		 /* SectionAlignment */
	const uint8_t *stub_bin; /* stub blob for this class */
	size_t		   stub_len;
	uint16_t	   nsec;	  /* original section count */
	int			   ei;		  /* entry section index */
	uint32_t	   dst_rva;	  /* RVA the stub decompresses the region back to */
	size_t		   payload;	  /* stub + compressed blob */
	size_t		   new_off;	  /* file offset of the .woody raw data */
	size_t		   new_raw;	  /* .woody SizeOfRawData (file-aligned) */
	uint32_t	   new_va;	  /* .woody VirtualAddress (== new entry) */
	uint32_t	   new_image; /* patched SizeOfImage */
} t_pe_layout;

/* Resolve the class-specific blob/alignments and lay out the .woody section.
 * Also sets f->out_len. Returns 0, or -1 if the entry section is unfindable. */
static int plan_output_pe(const t_pe *pe, t_file *f, t_pe_layout *lo)
{
	if (pe->is64)
	{
		const t_pe_opt_header64 *o = pe->opt;

		lo->fa = o->FileAlignment;
		lo->sa = o->SectionAlignment;
		lo->stub_bin = stubpe64_bin;
		lo->stub_len = stubpe64_bin_len;
	}
	else
	{
		const t_pe_opt_header32 *o = pe->opt;

		lo->fa = o->FileAlignment;
		lo->sa = o->SectionAlignment;
		lo->stub_bin = stubpe32_bin;
		lo->stub_len = stubpe32_bin_len;
	}
	lo->nsec = pe->fh->NumberOfSections;
	lo->ei = pe_entry_section(pe);
	if (lo->ei < 0)
		return (-1);
	lo->dst_rva = pe->sections[lo->ei].VirtualAddress;
	lo->payload = lo->stub_len + f->comp_len;
	lo->new_off = ALIGN_UP(f->size, lo->fa);
	lo->new_raw = ALIGN_UP(lo->payload, lo->fa);
	lo->new_va = (uint32_t)ALIGN_UP(pe_va_end(pe, lo->sa), lo->sa);
	lo->new_image
		= (uint32_t)ALIGN_UP((uint64_t)lo->new_va + lo->payload, lo->sa);
	f->out_len = lo->new_off + lo->new_raw;
	return (0);
}

/* Repoint the entry/image-size fields (whose offset differs by class) in the
 * output copy of the optional header. */
static void patch_opt_header_pe(uint8_t *out,
								size_t	 opt_off,
								int		 is64,
								uint32_t entry_va,
								uint32_t image_sz)
{
	if (is64)
	{
		t_pe_opt_header64 *oo = (t_pe_opt_header64 *)(out + opt_off);

		oo->AddressOfEntryPoint = entry_va;
		oo->SizeOfImage = image_sz;
		oo->CheckSum = 0;
	}
	else
	{
		t_pe_opt_header32 *oo = (t_pe_opt_header32 *)(out + opt_off);

		oo->AddressOfEntryPoint = entry_va;
		oo->SizeOfImage = image_sz;
		oo->CheckSum = 0;
	}
}

/* Patch the output copy: bump the section count, repoint the entry, make the
 * host code section writable (the stub's decompress target), and append the
 * .woody section header. */
static void patch_headers_pe(uint8_t			*out,
							 const t_pe			*pe,
							 const t_file		*f,
							 const t_pe_layout	*lo)
{
	const size_t	  opt_off = (const uint8_t *)pe->opt - f->data;
	t_pe_file_header *ofh
		= (t_pe_file_header *)(out + ((const uint8_t *)pe->fh - f->data));
	t_pe_section_header *secs = (t_pe_section_header *)(out
			+ ((const uint8_t *)pe->sections - f->data));
	t_pe_section_header *ns = &secs[lo->nsec];

	ofh->NumberOfSections = lo->nsec + 1;
	patch_opt_header_pe(out, opt_off, pe->is64, lo->new_va, lo->new_image);
	secs[lo->ei].Characteristics |= PE_SCN_MEM_WRITE; /* decompress target */
	memset(ns, 0, sizeof(*ns));
	memcpy(ns->Name, ".woody", 6);
	ns->VirtualSize = (uint32_t)lo->payload;
	ns->VirtualAddress = lo->new_va;
	ns->SizeOfRawData = (uint32_t)lo->new_raw;
	ns->PointerToRawData = (uint32_t)lo->new_off;
	ns->Characteristics = PE_SCN_WOODY;
}

/* Append a .woody RWX section (stub + encrypted/compressed blob), repoint the
 * entry at the stub, and make the host code section writable. Class-agnostic
 * except for the stub blob, the alignment fields, the entry/image-size fields
 * (whose offset differs between PE32 and PE32+), and the stub param width -- the
 * first three are settled by plan_output_pe / patch_headers_pe, leaving only the
 * last to branch on here. */
static int build_output_pe(t_file *f)
{
	t_pe		pe;
	t_pe_layout lo;
	uint8_t	   *out;

	if (pe_parse(f->data, f->size, &pe))
		return (-1);
	if (plan_output_pe(&pe, f, &lo))
		return (-1);
	out = calloc(1, f->out_len);
	if (!out)
		return (perror("malloc"), -1);
	memcpy(out, f->data, f->size);
	memcpy(out + lo.new_off, lo.stub_bin, lo.stub_len);
	memcpy(out + lo.new_off + lo.stub_len, f->blob, f->comp_len);
	if (pe.is64 ? fill_stub_pe64(out + lo.new_off, lo.stub_len, lo.new_va,
								 lo.dst_rva, f)
				: fill_stub_pe32(out + lo.new_off, lo.stub_len, lo.new_va,
								 lo.dst_rva, f))
		return (free(out), -1);
	patch_headers_pe(out, &pe, f, &lo);
	fprintf(stderr,
			"[woody] PE .woody @ rva %#x file %#zx  entry %#x -> %#x (%s)\n",
			lo.new_va,
			lo.new_off,
			(unsigned)f->entry,
			lo.new_va,
			pe.is64 ? "pe64" : "pe32");
	f->out = out;
	return (0);
}

/* Our output carries a ".woody" section; refuse to pack it again. */
static int is_packed_pe(const t_file *f)
{
	t_pe pe;

	if (pe_parse(f->data, f->size, &pe))
		return (0);
	for (uint16_t i = 0; i < pe.fh->NumberOfSections; i++)
		if (memcmp(pe.sections[i].Name, ".woody", 6) == 0)
			return (1);
	return (0);
}

/* One table serves both classes: the hooks branch on f->is64 internally, the
 * same way the shared pipeline does. */
static const t_file_ops g_pe = {
	.name = "pe",
	.validate = validate_pe,
	.find_region = find_region_pe,
	.build_output = build_output_pe,
	.is_packed = is_packed_pe,
};

const t_file_ops *pe_select_ops(const t_file *f)
{
	(void)f;
	return (&g_pe);
}

/* Set the class field the ops rely on (PE32+ vs PE32). */
int pe_prepare(t_file *f)
{
	t_pe pe;

	if (pe_parse(f->data, f->size, &pe))
		return (-1);
	f->is64 = pe.is64;
	return (0);
}
